import os
from databricks.sdk import WorkspaceClient
w = WorkspaceClient()
sch = os.environ['MLPAB_DATABRICKS_SCHEMA']
cat, s = sch.split('.')
for wh in w.warehouses.list():
    print('WH:', wh.id, wh.name, wh.state)
try:
    for t in w.tables.list(catalog_name=cat, schema_name=s):
        print('TABLE:', t.full_name)
except Exception as e:
    print('list err:', repr(e))
# recent query history
from databricks.sdk.service.sql import QueryFilter, TimeRange
import time
try:
    hist = w.query_history.list(max_results=10)
    for q in (hist.res or []):
        print('Q:', q.status, str(q.query_text)[:80].replace(chr(10),' '))
except Exception as e:
    print('hist err:', repr(e))
"

